import { ark } from "@ark-ui/solid/factory";
import {
  type ButtonGroupVariantProps,
  buttonGroupRecipe,
} from "@pisagor/recipes/button-group";
import { cn } from "@pisagor/utils";
import type { ComponentProps, JSX } from "solid-js";
import { splitProps } from "solid-js";
import { Separator, type SeparatorProps } from "../separator";
import { ButtonGroupContext, useButtonGroup } from "./button-group.context";

export interface ButtonGroupProps
  extends ComponentProps<typeof ark.fieldset>,
    ButtonGroupVariantProps {
  recipe?: typeof buttonGroupRecipe;
}

export type ButtonGroupTextProps = ComponentProps<typeof ark.div>;

export function ButtonGroupRoot(props: ButtonGroupProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "orientation",
    "children",
    "recipe",
    "class",
  ]);
  const slots = () =>
    (local.recipe ?? buttonGroupRecipe)({ orientation: local.orientation });

  return (
    <ButtonGroupContext value={{ slots: slots() }}>
      <ark.fieldset
        {...rest}
        class={slots().base({ class: cn(local.class) })}
        data-orientation={local.orientation}
        data-part="root"
        data-scope="button-group"
      >
        {local.children}
      </ark.fieldset>
    </ButtonGroupContext>
  );
}

export function ButtonGroupText(props: ButtonGroupTextProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useButtonGroup();

  return (
    <ark.div
      {...rest}
      class={slots.text({ class: cn(local.class) })}
      data-part="text"
      data-scope="button-group"
    />
  );
}

export function ButtonGroupSeparator(props: SeparatorProps): JSX.Element {
  const [local, rest] = splitProps(props, ["orientation", "class"]);
  const { slots } = useButtonGroup();

  return (
    <Separator
      {...rest}
      class={slots.separator({ class: cn(local.class) })}
      data-part="separator"
      data-scope="button-group"
      orientation={local.orientation ?? "vertical"}
    />
  );
}

import type { ButtonGroupRecipe } from "@pisagor/recipes/button-group";
import { createContext } from "../../utils";

interface ButtonGroupContextValue {
  slots: ButtonGroupRecipe;
}

export const { ButtonGroupContext, useButtonGroup } =
  createContext<ButtonGroupContextValue>()({
    name: "ButtonGroup",
  });

import {
  ButtonGroupRoot,
  ButtonGroupSeparator,
  ButtonGroupText,
} from "./button-group";

export type { ButtonGroupProps, ButtonGroupTextProps } from "./button-group";

export const ButtonGroup = Object.assign(ButtonGroupRoot, {
  Separator: ButtonGroupSeparator,
  Text: ButtonGroupText,
});

