export function RichCells() {
  const columns = createMemo<ColumnDef<User>[]>(() => [
    {
      cell: ({ row }) => (
        <div class="flex items-center gap-3">
          <Avatar
            fallback={row.original.name
              .split(" ")
              .map((part) => part[0])
              .join("")
              .slice(0, 2)}
            size="sm"
          />
          <div class="min-w-0">
            <p class="truncate font-medium">{row.original.name}</p>
            <p class="truncate text-muted-foreground text-xs">
              {row.original.email}
            </p>
          </div>
        </div>
      ),
      header: "Member",
      id: "member",
    },
    {
      accessorKey: "role",
      cell: ({ row }) => <Badge variant="secondary">{row.original.role}</Badge>,
      header: "Role",
    },
    {
      accessorKey: "department",
      header: "Department",
    },
    {
      accessorKey: "status",
      cell: ({ row }) => (
        <Badge class="capitalize" variant={statusVariants[row.original.status]}>
          {row.original.status}
        </Badge>
      ),
      header: "Status",
    },
    {
      accessorKey: "joinedAt",
      cell: ({ row }) => (
        <span class="text-muted-foreground tabular-nums">
          {formatDate(row.original.joinedAt)}
        </span>
      ),
      header: "Joined",
    },
  ]);

  return (
    <DataGridShell>
      <DataGrid<User> columns={columns()} data={allUsers.slice(0, 10)}>
        <DataGridView colSpan={5} />
      </DataGrid>
    </DataGridShell>
  );
}

