  FileContentProps,
  FileMediaProps,
  FileMetaProps,
  FileNameProps,
  FileProps,
  FileRootProps,
  FileSizeProps,
} from "./file";

export const File = Object.assign(FileShorthand, {
  Actions: FileActions,
  Content: FileContent,
  Media: FileMedia,
  Meta: FileMeta,
  Name: FileName,
