}

export function TimelineSeparator(props: TimelineSeparatorProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTimelineItem();
  return (
    <ark.div
      {...rest}
      aria-hidden="true"
      class={slots.separator({ class: cn(local.class) })}
      data-part="separator"
      data-scope="timeline"
    />
  );
}

export function TimelineContent(props: TimelineContentProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTimelineItem();
  return (
    <ark.div
      {...rest}
      class={slots.content({ class: cn(local.class) })}
      data-part="content"
      data-scope="timeline"
    />
  );
}

export function TimelineTitle(props: TimelineTitleProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTimelineItem();
  return (
    <ark.div
      {...rest}
      class={slots.title({ class: cn(local.class) })}
      data-part="title"
      data-scope="timeline"
    />
  );
}

export function TimelineDescription(
  props: TimelineDescriptionProps,
): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTimelineItem();
  return (
    <ark.div
      {...rest}
      class={slots.description({ class: cn(local.class) })}
      data-part="description"
      data-scope="timeline"
    />
  );
}

export function TimelineShorthand(props: TimelineProps): JSX.Element {
  const [local, rest] = splitProps(props, ["items"]);
  return (
    <TimelineRoot {...rest}>
      <For each={local.items ?? []}>
        {(item) => (
          <TimelineItem>
            <TimelineSeparator />
            <TimelineIndicator>{item.indicator}</TimelineIndicator>
            <TimelineContent>
              <TimelineTitle>{item.title}</TimelineTitle>
              <Show when={item.description}>
                <TimelineDescription>{item.description}</TimelineDescription>
              </Show>
            </TimelineContent>
          </TimelineItem>
        )}
      </For>
    </TimelineRoot>
  );
}

import type { TimelineItemRecipe } from "@pisagor/recipes/timeline";
import { createContext } from "../../utils";

interface TimelineItemContextValue {
  slots: TimelineItemRecipe;
}

export const { TimelineItemContext, useTimelineItem } =
  createContext<TimelineItemContextValue>()({
    name: "TimelineItem",
  });

import {
  TimelineContent,
  TimelineDescription,
  TimelineIndicator,
  TimelineItem,
  TimelineRoot,
  TimelineSeparator,
  TimelineShorthand,
  TimelineTitle,
} from "./timeline";

export type {
  TimelineContentProps,
  TimelineDescriptionProps,
  TimelineIndicatorProps,
  TimelineItemProps,
  TimelinePresetItem,
  TimelineProps,
  TimelineRootProps,
  TimelineSeparatorProps,
  TimelineTitleProps,
} from "./timeline";

export const Timeline = Object.assign(TimelineShorthand, {
  Content: TimelineContent,
  Description: TimelineDescription,
  Indicator: TimelineIndicator,
  Item: TimelineItem,
  Root: TimelineRoot,
  Separator: TimelineSeparator,
  Title: TimelineTitle,
});

