import { createTreeCollection } from "@pisagor/solid";
import type { TreeNodeType } from "@pisagor/solid/tree-view";
import { TreeView } from "@pisagor/solid/tree-view";
import { createSignal } from "solid-js";
export function CheckboxTree() {
  const collection = createTreeCollection({
    rootNode: {
      children: [
        {
          children: [
            { id: "app/page.tsx", name: "page.tsx" },
            { id: "app/layout.tsx", name: "layout.tsx" },
          ],
          id: "app",
          name: "app",
        },
        {
          children: [
            { id: "components/button.tsx", name: "button.tsx" },
            { id: "components/input.tsx", name: "input.tsx" },
          ],
          id: "components",
          name: "components",
        },
        { id: "package.json", name: "package.json" },
        { id: "readme.md", name: "README.md" },
      ],
      id: "ROOT",
      name: "",
    },
  });

  const TreeNode = ({
    indexPath,
    node,
  }: {
    node: TreeNodeType;
    indexPath: number[];
  }) => {
    return (
      <TreeView.NodeProvider indexPath={indexPath} node={node}>
        {node.children ? (
          <TreeView.Branch>
            <TreeView.BranchControl>
              <TreeView.NodeCheckbox />
              {node.name}
            </TreeView.BranchControl>
            <TreeView.BranchContent>
              {node.children.map((child, index) => (
                <TreeNode indexPath={[...indexPath, index]} node={child} />
              ))}
            </TreeView.BranchContent>
          </TreeView.Branch>
        ) : (
          <TreeView.Item>
            <TreeView.NodeCheckbox />
            <TreeView.ItemText>{node.name}</TreeView.ItemText>
          </TreeView.Item>
        )}
      </TreeView.NodeProvider>
    );
  };
  const [checkedNodes, setCheckedNodes] = createSignal<string[]>(["readme.md"]);

  return (
    <div class="flex items-center gap-2">
      <div>
        <TreeView
          checkedValue={checkedNodes()}
          collection={collection}
          onCheckedChange={({ checkedValue }) => setCheckedNodes(checkedValue)}
        >
          <TreeView.Tree>
            {collection.rootNode.children?.map((node, index) => (
              <TreeNode indexPath={[index]} node={node} />
            ))}
          </TreeView.Tree>
        </TreeView>
      </div>
      <p class="whitespace-pre-wrap text-muted-foreground text-sm">
        {JSON.stringify(checkedNodes, null, 2)}
      </p>
    </div>
  );
}

